T = int(input())
for t in range(1, T + 1):
	inp = input().split()
	N = int(inp[0])
	K = int(inp[1])
	A = list(map(int, input().split()))
	cnt = 0
	freq = {}
	for a in A:
		if a in freq.keys():
			cnt += freq[a]
		val = K - a ^ a
		if val in freq.keys():
			freq[val] += 1
		else:
			freq[val] = 1
	print(cnt)
